ient(\\n        // Supabase API URL - env var exported by default.\\n        Deno.env.get('SUPABASE_URL') ?? '',\\n        // Supabase API PUBLISHABLE KEY - env var exported by default.\\n        Deno.env.get(SUPABASE_PUBLISHABLE_KEYS['default']) ?? '',\\n        // Create client with Auth context of the user that called the function.\\n        // This way your row-level-security (RLS) policies are applied.\\n        {\\n          global: {\\n            headers: { Authorization: req.headers.get('Authorization')! },\\n          },\\n        }\\n      )\\n\\n      // First get the token from the Authorization header\\n      const token = req.headers.get('Authorization').replace('Bearer ', '')\\n\\n      // Now we can get the session or user object\\n      const {\\n        data: { user },\\n      } = await supabaseClient.auth.getUser(token)\\n\\n      // And we can run queries in the context of our authenticated user\\n      const { data, error } = await supabaseClient.from('users').select('*')\\n      if (error) throw error\\n\\n      return new Response(JSON.stringify({ user, data }), {\\n        headers: { ...corsHeaders, 'Content-Type': 'application/json' },\\n        status: 200,\\n      })\\n    } catch (error) {\\n      return new Response(JSON.stringify({ error: error.message }), {\\n        headers: { ...corsHeaders, 'Content-Type': 'application/json' },\\n        status: 400,\\n      })\\n    }\\n  })\\n\\n  // To invoke:\\n  // curl -i --location --request POST 'http://localhost:54321/functions/v1/select-from-table-with-auth-rls' \\\\\\n  //   --header 'Authorization: Bearer REDACTED_JWT' \\\\\\n  //   --header 'Content-Type: application/json' \\\\\\n  //   --data '{\\\"name\\\":\\\"Functions\\\"}'\\n  ```\\n</CodeSampleWrapper>\\n\"},{\"title\":\"Integrating with Supabase Database (Postgres)\",\"href\":\"https://supabase.com/docs/guides/functions/connect-to-postgres\",\"content\":\"# Integrating with Supabase Database (Postgres)\\n\\nConnect to your Postgres database from Edge Functions.\\n\\nConnect to your Postgres database from an Edge Function by using the `supabase-js` client.\\nYou can also use other Postgres clients like [Deno Postgres](https://deno.land/x/postgres)\\n\\n***\\n\\n\\n## Using supabase-js\\n\\nThe `supabase-js` client handles authorization with Row Level Security and automatically formats responses as JSON. This is the recommended approach for most applications:\\n\\n```ts index.ts\\nimport { createClient } from 'npm:@supabase/supabase-js@2'\\n\\nDeno.serve(async (req) => {\\n  try {\\n    const supabase = createClient(\\n      Deno.env.get('SUPABASE_URL') ?? '',\\n      Deno.env.get('SUPABASE_PUBLISHABLE_KEY') ?? '',\\n      { global: { headers: { Authorization: req.headers.get('Authorization')! } } }\\n    )\\n\\n    const { data, error } = await supabase.from('countries').select('*')\\n\\n    if (error) {\\n      throw error\\n    }\\n\\n    return new Response(JSON.stringify({ data }), {\\n      headers: { 'Content-Type': 'application/json' },\\n      status: 200,\\n    })\\n  } catch (err) {\\n    return new Response(String(err?.message ?? err), { status: 500 })\\n  }\\n})\\n```\\n\\nThis enables:\\n\\n*   Automatic Row Level Security enforcement\\n*   Built-in JSON serialization\\n*   Consistent error handling\\n*   TypeScript support for database schema\\n\\n***\\n\\n\\n## Using a Postgres client\\n\\nBecause Edge Functions are a server-side technology, it's safe to connect directly to your database using any popular Postgres client. This means you can run raw SQL from your Edge Functions.\\n\\nHere is how you can connect to the database using Deno Postgres driver and run raw SQL. Check out the [full example](https://github.com/supabase/supabase/tree/master/examples/edge-functions/supabase/functions/postgres-on-the-edge).\\n\\n<CodeSampleWrapper source=\\\"https://github.com/supabase/supabase/blob/master/examples/edge-functions/supabase/functions/postgres-on-the-edge/index.ts\\\">\\n  ```typescript\\n  import { Pool } from 'https://deno.land/x/postgres@v0.17.0/mod.ts'\\n\\n  // Create a database pool with one connection.\\n  const pool = new Pool(\\n    {\\n      tls: { enabled: false },\\n      database: 'postgres',\\n      hostname: Deno.env.get('DB_HOSTNAME'),\\n      user: Deno.env.get('DB_USER'),\\n      port: 6543,\\n      password: Deno.env.get('DB_PASSWORD'),\\n    },\\n    1\\n  )\\n\\n  Deno.serve(async (_req) => {\\n    try {\\n      // Grab a connection from the pool\\n      const connection = await pool.connect()\\n\\n      try {\\n        // Run a query\\n        const result = await connection.queryObject`SELECT * FROM animals`\\n        const animals = result.rows // [{ id: 1, name: \\\"Lion\\\" }, ...]\\n\\n        // Encode the result as pretty printed JSON\\n        const body = JSON.stringify(\\n          animals,\\n          (_key, value) => (typeof value === 'bigint' ? value.toString() : value),\\n          2\\n        )\\n\\n        // Return the response with the correct content type header\\n        return new Response(body, {\\n          status: 200,\\n          headers: {\\n            'Content-Type': 'application/json; charset=utf-8',\\n          },\\n        })\\n      } finally {\\n        // Release the connection back into the pool\\n        connection.release()\\n      }\\n    } catch (err) {\\n      console.error(err)\\n      return new Response(String(err?.message ?? err), { status: 500 })\\n    }\\n  })\\n  ```\\n</CodeSampleWrapper>\\n\\n***\\n\\n\\n## Using Drizzle\\n\\nYou can use Drizzle together with [Postgres.js](https://github.com/porsager/postgres). Both can be loaded directly from npm.\\n\\nDeclare the dependencies in a `deno.json` file inside the function directory (see [Managing functions dependencies](/docs/guides/functions/dependencies) for more details):\\n\\n<CodeSampleWrapper source=\\\"https://github.com/supabase/supabase/blob/master/examples/edge-functions/supabase/functions/drizzle/deno.json\\\">\\n  ```json\\n  {\\n    \\\"imports\\\": {\\n      \\\"drizzle-orm\\\": \\\"npm:drizzle-orm@0.29.1\\\",\\n      \\\"drizzle-orm/\\\": \\\"npm:/drizzle-orm@0.29.1/\\\",\\n      \\\"postgres\\\": \\\"npm:postgres@3.4.3\\\"\\n    }\\n  }\\n  ```\\n</CodeSampleWrapper>\\n\\nThen define your schema and query the database:\\n\\n{/* prettier-ignore */}\\n\\n<CodeSampleWrapper source=\\\"https://github.com/supabase/supabase/blob/master/examples/edge-functions/supabase/functions/_shared/schema.ts\\\">\\n  ```typescript\\n  import { pgTable, serial, text, timestamp } from 'drizzle-orm/pg-core'\\n\\n  export const user = pgTable('user', {\\n    id: serial('id'),\\n    name: text('name'),\\n    email: text('email'),\\n    password: text('password'),\\n    role: text('role').$type<'admin' | 'customer'>(),\\n    createdAt: timestamp('created_at'),\\n    updatedAt: timestamp('updated_at'),\\n  })\\n\\n  export const countries = pgTable('countries', {\\n    id: serial('id'),\\n    name: text('name'),\\n  })\\n  ```\\n</CodeSampleWrapper>\\n\\n<CodeSampleWrapper source=\\\"https://github.com/supabase/supabase/blob/master/examples/edge-functions/supabase/functions/drizzle/index.ts\\\">\\n  ```typescript\\n  import { drizzle } from 'drizzle-orm/postgres-js'\\n  import postgres from 'postgres'\\n  import { countries } from '../_shared/schema.ts'\\n\\n  const connectionString = Deno.env.get('SUPABASE_DB_URL')!\\n  // Disable prefetch as it is not supported for \\\"Transaction\\\" pool mode\\n  const client = postgres(connectionString, { prepare: false })\\n  const db = drizzle(client)\\n\\n  Deno.serve(async (_req) => {\\n    const allCountries = await db.select().from(countries)\\n\\n    return Response.json(allCountries)\\n  })\\n  ```\\n</CodeSampleWrapper>\\n\\nYou can find the full example on [GitHub](https://github.com/supabase/supabase/tree/master/examples/edge-functions/supabase/functions/drizzle).\\n\\n***\\n\\n\\n## SSL connections\\n\\n\\n### Production\\n\\nDeployed edge functions are pre-configured to use SSL for connections to the Supabase database. You don't need to add any extra configurations.\\n\\n\\n### Local development\\n\\nIf you want to use SSL connections during local development, follow these steps:\\n\\n1.  Download the SSL certificate from [Database Settings](/dashboard/project/_/database/settings)\\n2.  Add to your [local .env file](/docs/guides/functions/secrets), add these two variables:\\n\\n```bash\\nSSL_CERT_FILE=/path/to/cert.crt # set the path to the downloaded cert\\nDENO_TLS_CA_STORE=mozilla,system\\n```\\n\\nThen, restart your local development server:\\n\\n```bash\\nsupabase functions serve your-function\\n```\\n\"},{},{\"title\":\"Which package to use\",\"href\":\"https://supabase.com/docs/guides/auth/choosing-a-server-package\",\"content\":\"# Which package to use\\n\\nWhen to use supabase-js, @supabase/ssr, or @supabase/server on the server.\\n\\nWhen you use Supabase from JavaScript on the server, there are three packages to choose from. They are not alternatives to each other — `@supabase/ssr` and `@supabase/server` both build on top of `supabase-js` and solve different problems. This guide helps you pick the right one.\\n\\n<Admonition type=\\\"note\\\">\\n  These are JavaScript packages, not separate language SDKs. If you're looking for the client library for another language (Python, Swift, Kotlin, etc.), see the [client library references](/docs/reference).\\n</Admonition>\\n\\n\\n## Which package to use\\n\\nThe quickest way to decide is by **how the user's identity reaches your code**:\\n\\n*   The session lives in **cookies** (an SSR framework like Next.js or SvelteKit) → use **`@supabase/ssr`**.\\n*   Auth arrives **per request in headers** (`Authorization: Bearer <jwt>`) → use **`@supabase/server`**.\\n*   You want the base client, or you're handling auth yourself → use **`@supabase/supabase-js`** directly.\\n\\n| Package                 | Use it when                                           | Runs in                                                                             | Auth model                                         |\\n| ----------------------- | ----------------------------------------------------- | ----------------------------------------------------------------------------------- | -------------------------------------------------- |\\n| `@supabase/supabase-js` | You want the base client, or you manage auth yourself | Browser and server                                                                  | You wire up auth                                   |\\n| `@supabase/ssr`         | User sessions are stored in **cookies**               | SSR frameworks (Next.js, SvelteKit, TanStack Start)                                 | Cookie-based sessions, with refresh-token rotation |\\n| `@supabase/server`      | Auth arrives **per request in headers**               | Edge Functions, Workers, Vercel, Bun, and framework APIs (Hono, H3, Elysia, NestJS) | Stateless Bearer JWT + `apikey`                    |\\n\\n\\n## `@supabase/supabase-js`\\n\\nThe isomorphic base client. `@supabase/ssr` and `@supabase/server` both wrap it — reach for `supabase-js` directly when you don't need either wrapper's auth handling.\\n\\n```ts\\nimport { createClient } from '@supabase/supabase-js'\\n\\nconst supabase = createClient(process.env.SUPABASE_URL!, process.env.SUPABASE_PUBLISHABLE_KEY!)\\n```\\n\\n\\n## `@supabase/ssr`\\n\\nFor SSR frameworks that store the user's session in cookies. It reads and writes session cookies and handles refresh-token rotation, so the same user and session are available on both the client and the server.\\n\\n```ts\\nimport { createServerClient } from '@supabase/ssr'\\n\\nconst supabase = createServerClient(\\n  process.env.SUPABASE_URL!,\\n  process.env.SUPABASE_PUBLISHABLE_KEY!,\\n  {\\n    cookies: {\\n      getAll() {\\n        // return the request's cookies\\n      },\\n      setAll(cookiesToSet) {\\n        // write cookies back on the response\\n      },\\n    },\\n  }\\n)\\n```\\n\\nSee the [server-side rendering guide](/guides/auth/server-side) for framework-specific setup.\\n\\n\\n## `@supabase/server`\\n\\nFor stateless, header-based auth in backend runtimes — Edge Functions, Workers, and framework APIs. You declare who may call an endpoint and receive a ready-to-use context (a caller-scoped client that respects RLS, plus an admin client). It verifies JWTs and resolves the new API keys (`SUPABASE_PUBLISHABLE_KEYS` / `SUPABASE_SECRET_KEYS`) for you.\\n\\n```ts\\nimport { withSupabase } from '@supabase/server'\\n\\nexport default {\\n  fetch: withSupabase({ auth: 'user' }, async (req, ctx) => {\\n    // ctx.supabase is scoped to the caller and respects RLS\\n    const { data } = await ctx.supabase.from('todos').select()\\n    return Response.json(data)\\n  }),\\n}\\n```\\n\\nSee the [`@supabase/server` reference](/docs/reference/server) for the full API.\\n\\n<Admonition type=\\\"note\\\">\\n  `@supabase/ssr` and `@supabase/server` coexist and are not replacements for each other, and `@supabase/ssr` is not deprecated. Pick based on where your code runs and how auth reaches it, using the table above.\\n</Admonition>\\n\\n\\n## Advanced: Combining `@supabase/server` and `@supabase/ssr`\\n\\nIn a cookie-based framework you can compose the two — let `@supabase/ssr` own the cookie session lifecycle and hand the resolved token to `@supabase/server`'s primitives. This requires more setup, and deeper first-party integration is on the roadmap. See the [`@supabase/server` SSR frameworks guide](https://github.com/supabase/server/blob/main/docs/ssr-frameworks.md).\\n\\n\\n## Next steps\\n\\n*   [Server-side rendering](/guides/auth/server-side) — set up `@supabase/ssr` for your framework.\\n*   [`@supabase/server` reference](/docs/reference/server) — API for header-based server auth.\\n*   [`supabase-js` reference](/docs/reference/javascript) — the base JavaScript client.\\n\"},{\"title\":\"\",\"href\":\"https://supabase.com/docs/reference/javascript/oauth-admin-createclient\",\"content\":\"# JavaScript Reference\\n\\n\\n\\nCreates a new OAuth client.\\nOnly relevant when the OAuth 2.1 server is enabled in Supabase Auth.\\n\\nThis function should only be called on a server. Never expose your `service_role` key in the browser.\\n\\n## Examples\\n\\n\",\"methodName\":\"createClient\",\"language\":\"JAVASCRIPT\"}]}}}"
