      "content": "import { createClient } from "npm:@supabase/supabase-js@2";

const jsonHeaders = { "Content-Type": "application/json" };

function errorResponse(message: string, status: number): Response {
  return new Response(JSON.stringify({ error: message }), {
    status,
    headers: jsonHeaders,
  });
}

Deno.serve(async (req: Request): Promise<Response> => {
  if (req.method !== "POST") {
    return errorResponse("Method not allowed", 405);
  }

  const authorization = req.headers.get("Authorization");
  if (!authorization) {
    return errorResponse("Authorization header is required", 401);
  }

  let payload: unknown;
  try {
    payload = await req.json();
  } catch {
    return errorResponse("Invalid JSON body", 400);
  }

  if (
    typeof payload !== "object" ||
    payload === null ||
    !("body" in payload) ||
    typeof (payload as { body?: unknown }).body !== "string"
  ) {
    return errorResponse("The body field is required", 400);
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? "",
    {
      global: {
        headers: { Authorization: authorization },
      },
    },
  );

  const { data, error } = await supabase
    .from("todos")
    .insert({ body: (payload as { body: string }).body })
    .select()
    .single();

  if (error || !data) {
    return errorResponse(error?.message ?? "Failed to create todo", 500);
  }

  return new Response(JSON.stringify(data), {
    status: 201,
    headers: jsonHeaders,
  });
});
